INSERT INTO public.products (id, nome, sabor, categoria, preco, volume_ml, estoque, notas_aromaticas, descricao, sugestoes, foto_url, ativo, graduacao_gl, brix, pedidos_count, ordem, created_at, updated_at, ingredientes, fotos) VALUES ('631512a9-16dc-4e4f-8f07-98278a207c0a', 'Poção do Aconchego', 'Canela', 'fino', 38, 750, 5, 'Especiado • Quente • Amadeirado', 'Aroma quente e envolvente, especiaria suave que aquece o paladar.', 'Servir gelado, puro, após refeições (digestivo). Em coquetéis autorais (ex: Canela Sour) ou para aromatizar vinho quente (quentão). Combina com sobremesas de canela, chocolate e frutas assadas (maçã, pera).', 'https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951827467-tk8ajr/card.webp', true, 18, 41, 0, 5, '2026-05-15T20:15:03.142933+00:00', '2026-07-02T00:26:46.65937+00:00', 'Açúcar, Álcool de Cereais, Canela em pau e Anis estrelado.', '[{"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951827467-tk8ajr/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951827467-tk8ajr/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951827467-tk8ajr/thumb.webp"}, {"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951830605-nsaa0u/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951830605-nsaa0u/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951830605-nsaa0u/thumb.webp"}]'::jsonb);
INSERT INTO public.products (id, nome, sabor, categoria, preco, volume_ml, estoque, notas_aromaticas, descricao, sugestoes, foto_url, ativo, graduacao_gl, brix, pedidos_count, ordem, created_at, updated_at, ingredientes, fotos) VALUES ('6fe04098-9cd1-4cb7-a903-1e3ae1147671', 'Poção Néctar Místico', 'Butiá', 'fino', 38, 750, 0, 'Cítrica • Frutada • Leve', 'Sabor exótico, com doçura suave e com notas citricas.', 'Servir gelado, puro ou on the rocks. Em drinks sour cítricos (ex: butiá sour com cachaça e limão). Acompanha pratos leves (saladas tropicais, peixes) ou queijos suaves.', 'https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951668638-7fpfi5/card.webp', true, 16, 35, 4, 3, '2026-05-15T20:15:03.142933+00:00', '2026-07-02T00:21:02.348072+00:00', 'Açúcar, Álcool de Cereais e Polpa de butiá.', '[{"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951668638-7fpfi5/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951668638-7fpfi5/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951668638-7fpfi5/thumb.webp"}, {"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951672491-2ydy1b/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951672491-2ydy1b/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951672491-2ydy1b/thumb.webp"}]'::jsonb);
INSERT INTO public.products (id, nome, sabor, categoria, preco, volume_ml, estoque, notas_aromaticas, descricao, sugestoes, foto_url, ativo, graduacao_gl, brix, pedidos_count, ordem, created_at, updated_at, ingredientes, fotos) VALUES ('af94b5a9-33d4-4a6b-abb1-0e59a49d3ec7', 'Poção da Prosperidade', 'Ouro Especial', 'especial', 50, 750, 5, 'Mística • Especiado • Aromático', 'Licor sedoso à base de leite, com infusão de café e especiarias. Notas de baunilha, cacau e noz-moscada, com leve toque cítrico, final suave e aveludado.', 'Temperatura levemente fria: servir em taça pequena a cerca de 10–15 °C.  Puro ou com gelo: degustar solo, como digestivo aromático após refeição. Não exagerar em gelo para não ofuscar as especiarias. Drinks criativos: substituir aguardente ou vodka em coquetéis de café (ex., martini de baunilha) para obter cremosidade extra.', 'https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952241189-9q8x00/card.webp', true, 12.5, 31, 8, 12, '2026-05-15T20:15:03.142933+00:00', '2026-07-16T00:55:08.80911+00:00', 'Açúcar, Leite Integral, Álcool de Cereais, Limão siciliano, Café, Cacau 100%, Noz-moscada e Essência de baunilha.', '[{"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952241189-9q8x00/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952241189-9q8x00/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952241189-9q8x00/thumb.webp"}, {"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952245204-c3aeu7/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952245204-c3aeu7/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952245204-c3aeu7/thumb.webp"}]'::jsonb);
INSERT INTO public.products (id, nome, sabor, categoria, preco, volume_ml, estoque, notas_aromaticas, descricao, sugestoes, foto_url, ativo, graduacao_gl, brix, pedidos_count, ordem, created_at, updated_at, ingredientes, fotos) VALUES ('d5941952-c8de-4cfa-a2d5-9ca89b0cf19a', 'Poção do Desejo', 'Chocolate Cremoso', 'cremoso', 45, 750, 5, 'Intenso • Cacau • Aveludado', 'Licor cremoso com cacau e chocolate nobre meio amargo, textura aveludada e final intenso e marcante.', 'Puro e gelado em taça pequena, como digestivo. Serve para encerrar uma refeição com aveludado sabor de cacau. Sobre sobremesas: como pudim de leite, sorvetes e bolos de chocolate.  Bebidas quentes como café expresso ou cappuccino, realçando notas torradas. Coquetelaria: base para drinks cremosos (White Russian, Alexander) substituindo licor de café. Garante cor e sabor chocolate intenso.', 'https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952235991-lscovx/card.webp', true, 11.5, 37, 3, 9, '2026-05-15T20:15:03.142933+00:00', '2026-07-02T00:32:03.321401+00:00', 'Açúcar, Álcool de Cereais, Leite condensado, Cacau 50% e Chocolate nobre meio amargo.', '[{"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952235991-lscovx/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952235991-lscovx/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952235991-lscovx/thumb.webp"}, {"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952239387-7nrj8d/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952239387-7nrj8d/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952239387-7nrj8d/thumb.webp"}, {"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952243751-3c3y23/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952243751-3c3y23/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952243751-3c3y23/thumb.webp"}]'::jsonb);
INSERT INTO public.products (id, nome, sabor, categoria, preco, volume_ml, estoque, notas_aromaticas, descricao, sugestoes, foto_url, ativo, graduacao_gl, brix, pedidos_count, ordem, created_at, updated_at, ingredientes, fotos) VALUES ('b0d77291-b5ed-4548-8837-887f674c1b4c', 'Poção da Alegria', 'Banana', 'fino', 38, 750, 3, 'Doce • Aveludada • Baunilha', 'Bebida com bastante perfume da fruta e com doçura suave', 'Degustar gelado, puro. Em coquetéis com gin ou rum (ex: Banana Daiquiri). Harmoniza com sobremesas cremosas (chocolate, doce de leite) e café.', 'https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951635297-p8c2yq/card.webp', true, 22.5, 25, 5, 2, '2026-05-15T20:15:03.142933+00:00', '2026-07-02T00:20:28.472564+00:00', 'Açúcar, Álcool de Cereais, Banana caturra, Açúcar mascavo, Canela em pau, Essência de baunilha e Cravo-da-Índia.', '[{"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951635297-p8c2yq/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951635297-p8c2yq/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951635297-p8c2yq/thumb.webp"}, {"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951638297-myl8uj/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951638297-myl8uj/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951638297-myl8uj/thumb.webp"}]'::jsonb);
